package ru.gits.task.telecom.cal;

/**
 * Phone number helpers.
 */
public final class PhoneNumbers {

    private PhoneNumbers() {
    }

    /**
     * Normalizes a Russian phone number to eleven digits starting with 7.
     *
     * @throws IllegalArgumentException when the text is not a Russian phone number
     */
    public static String normalize(String raw) {
        if (raw == null) {
            throw new IllegalArgumentException("Номер телефона не может быть null");
        }

        // Используем StringBuilder для быстрой сборки только цифр
        StringBuilder digits = new StringBuilder();

        for (int i = 0; i < raw.length(); i++) {
            char ch = raw.charAt(i);

            // Если это цифра, добавляем её в сборщик
            if (Character.isDigit(ch)) {
                digits.append(ch);
            } else if (ch != ' ' && ch != '(' && ch != ')' && ch != '-' && ch != '+') {
                // Если встретился любой другой символ (например, буква), номер некорректен
                throw new IllegalArgumentException("Недопустимый символ в номере телефона: " + ch);
            }
        }

        // Если это российская восьмерка, заменяем её на семерку
        if (digits.length() > 0 && digits.charAt(0) == '8') {
            digits.setCharAt(0, '7');
        }

        String result = digits.toString();

        // Проверяем финальные требования: ровно 11 цифр и первая из них — 7
        if (result.length() != 11 || result.charAt(0) != '7') {
            throw new IllegalArgumentException("Номер должен состоять из 11 цифр и начинаться с 7 или 8");
        }

        return result;
    }
}

